import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { findJobRowByKey, getJobRow, insertJob, listJobRows, toJob } from './store.ts';
import { parseIdempotencyKey, parseSubmission, type FieldError } from './validate.ts';

/** The worker counts as up if its heartbeat is at most this old. */
const WORKER_FRESH_MS = 3000;
const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

/** Reads the whole body as text, or returns null if it exceeds MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function safeDecode(s: string): string | undefined {
  try {
    return decodeURIComponent(s);
  } catch {
    return undefined;
  }
}

function health(res: ServerResponse): void {
  const hb = db.prepare("SELECT ts FROM heartbeat WHERE name = 'worker'").get() as { ts: number } | undefined;
  const up = hb !== undefined && Date.now() - Number(hb.ts) <= WORKER_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const text = await readBody(req);
  if (text === null) {
    return sendError(res, 400, 'invalid_request', 'The submission is invalid.', [{ field: 'body', message: 'body is too large' }]);
  }
  const submission = parseSubmission(req.headers['content-type'], text);
  const rawKey = req.headers['idempotency-key'];
  const key = parseIdempotencyKey(Array.isArray(rawKey) ? rawKey.join(', ') : rawKey);
  if (!submission.ok || !key.ok) {
    const fields = [...(submission.ok ? [] : submission.fields), ...(key.ok ? [] : key.fields)];
    return sendError(res, 400, 'invalid_request', 'The submission is invalid.', fields);
  }

  const { value } = submission;
  if (key.value !== null) {
    const existing = findJobRowByKey(db, key.value);
    if (existing) {
      const samePayload =
        existing.input === value.input && existing.steps === value.steps && existing.fail_attempts === value.failAttempts;
      if (samePayload) return send(res, 200, toJob(existing));
      return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    }
  }

  // The lookup above and this insert run in one synchronous block, so no other request can
  // interleave between them within this process.
  const row = insertJob(db, { ...value, idempotencyKey: key.value }, Date.now());
  send(res, 201, toJob(row));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  let allowed: string[] | undefined;
  let jobId: string | undefined;
  if (pathname === '/health' || pathname === '/') {
    allowed = ['GET'];
  } else if (pathname === '/api/jobs') {
    allowed = ['GET', 'POST'];
  } else {
    const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
    if (match) {
      allowed = ['GET'];
      jobId = safeDecode(match[1]!);
    }
  }
  if (!allowed || (pathname.startsWith('/api/jobs/') && jobId === undefined)) {
    return sendError(res, 404, 'not_found', 'No such route.');
  }
  if (!allowed.includes(method)) {
    return send(res, 405, { error: { code: 'method_not_allowed', message: `Use ${allowed.join(' or ')} for this route.` } }, { allow: allowed.join(', ') });
  }

  if (pathname === '/health') return health(res);
  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') return createJob(req, res);
    return send(res, 200, { jobs: listJobRows(db).map(toJob) });
  }
  const row = getJobRow(db, jobId!);
  if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
  send(res, 200, toJob(row));
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

